INSERT INTO electoral_stage.option_column(series_id,literal_header,column_ordinal,option_type,classification_evidence) SELECT s.series_id,om.literal_header,om.column_ordinal,om.option_type,'CATALOG_V0_1_LITERAL_COLUMN' FROM option_map om JOIN electoral_stage.source_release rel ON rel.outer_zip_sha256=om.zip_sha JOIN electoral_stage.source_member mem ON mem.release_id=rel.release_id AND mem.member_path=om.member_path JOIN electoral_stage.election_series s ON s.member_id=mem.member_id;
