-- HEYTI proyección 23 series v0.1. SOLO BASE TEMPORAL con 73262 filas crudas.
BEGIN;
CREATE TEMP TABLE option_map(zip_sha char(64),member_path text,literal_header text,column_ordinal integer,option_type text) ON COMMIT DROP;
DO $$ BEGIN IF (SELECT count(*) FROM electoral_stage.option_column)<>524 THEN RAISE EXCEPTION 'Catálogo distinto de 524'; END IF; END $$;
COMMIT;
CREATE TEMP VIEW projected_rows AS
SELECT s.series_id,s.election_year,s.election_type,s.modality,r.member_id,r.raw_row_id,r.raw_cells,
 r.raw_cells->>'SECCION' AS section_code,
 CASE WHEN r.raw_cells->>'SECCION'='0' THEN
  'SEC0:'||jsonb_build_array(CASE WHEN s.election_type IN ('DF','P','S') THEN coalesce(r.raw_cells->>'ID_DISTRITO_FEDERAL',r.raw_cells->>'ID_DISTRITO','') ELSE '' END,
    coalesce(r.raw_cells->>'ID_DISTRITO_LOCAL',''),coalesce(r.raw_cells->>'ID_MUNICIPIO',''),coalesce(r.raw_cells->>'MUNICIPIO',''))::text
 ELSE 'SEC:'||(r.raw_cells->>'SECCION') END AS unit_key,
 CASE WHEN r.raw_cells->>'SECCION'<>'0' THEN 'ORDINARY_SECTION'
      WHEN r.raw_cells->>'MUNICIPIO'='VOTO EN EL EXTRANJERO' THEN 'SPECIAL_AGGREGATE'
      ELSE 'SPECIAL_SECTION_ROW' END AS unit_kind,
 CASE WHEN s.election_type IN ('DF','P','S') THEN coalesce(r.raw_cells->>'ID_DISTRITO_FEDERAL',r.raw_cells->>'ID_DISTRITO') END AS district_federal_code,
 r.raw_cells->>'ID_DISTRITO_LOCAL' AS district_local_code,
 r.raw_cells->>'ID_MUNICIPIO' AS municipality_code
FROM electoral_stage.election_series s JOIN electoral_stage.raw_row r ON r.member_id=s.member_id;
-- Lote 2018: 28237 unidades, 812581 celdas, 276022 vacíos.
BEGIN;
SELECT r.series_id,r.unit_key,r.unit_kind,r.section_code,r.raw_cells->>'ID_ESTADO',r.district_federal_code,r.district_local_code,r.municipality_code,
 jsonb_build_object('ID_ESTADO',r.raw_cells->>'ID_ESTADO','ID_DISTRITO_FEDERAL',r.district_federal_code,'ID_DISTRITO_LOCAL',r.district_local_code,
 'ID_MUNICIPIO',r.municipality_code,'MUNICIPIO',r.raw_cells->>'MUNICIPIO','SECCION',r.section_code),'UNREVIEWED','UNRESOLVED'
FROM projected_rows r WHERE r.election_year=2018;
SELECT r.series_id,r.member_id,u.unit_id,r.raw_row_id,NULLIF(r.raw_cells->>'TOTAL_VOTOS','')::bigint,NULLIF(r.raw_cells->>'LISTA_NOMINAL','')::bigint,
 r.raw_cells->>'TOTAL_VOTOS',r.raw_cells->>'LISTA_NOMINAL',
 CASE WHEN r.raw_cells->>'TOTAL_VOTOS'='' THEN 'SOURCE_MISSING' WHEN r.raw_cells->>'TOTAL_VOTOS'='0' THEN 'OFFICIAL_ZERO' ELSE 'OBSERVED_DATA' END,
 CASE WHEN r.raw_cells->>'LISTA_NOMINAL'='' THEN 'SOURCE_MISSING' WHEN r.raw_cells->>'LISTA_NOMINAL'='0' THEN 'OFFICIAL_ZERO' ELSE 'OBSERVED_DATA' END,
 CASE WHEN r.raw_cells->>'TOTAL_VOTOS'='' THEN 'SOURCE_BLANK_UNCLASSIFIED' END,
 CASE WHEN r.raw_cells->>'LISTA_NOMINAL'='' THEN 'SOURCE_BLANK_UNCLASSIFIED' END
FROM projected_rows r JOIN electoral_stage.computation_unit u ON u.series_id=r.series_id AND u.unit_key=r.unit_key WHERE r.election_year=2018;
SELECT t.series_id,t.tally_id,o.option_id,NULLIF(r.raw_cells->>o.literal_header,'')::bigint,r.raw_cells->>o.literal_header,
 CASE WHEN r.raw_cells->>o.literal_header='' THEN 'SOURCE_MISSING' WHEN r.raw_cells->>o.literal_header='0' THEN 'OFFICIAL_ZERO' ELSE 'OBSERVED_DATA' END,
 CASE WHEN r.raw_cells->>o.literal_header='' THEN 'SOURCE_BLANK_UNCLASSIFIED' END
FROM electoral_stage.section_tally t JOIN electoral_stage.election_series s ON s.series_id=t.series_id
JOIN electoral_stage.raw_row r ON r.raw_row_id=t.raw_row_id JOIN electoral_stage.option_column o ON o.series_id=t.series_id
WHERE s.election_year=2018;
DO $$ BEGIN
 IF (SELECT count(*) FROM electoral_stage.computation_unit u JOIN electoral_stage.election_series s ON s.series_id=u.series_id WHERE s.election_year=2018)<>28237
 OR (SELECT count(*) FROM electoral_stage.section_tally t JOIN electoral_stage.election_series s ON s.series_id=t.series_id WHERE s.election_year=2018)<>28237
 OR (SELECT count(*) FROM electoral_stage.option_vote v JOIN electoral_stage.election_series s ON s.series_id=v.series_id WHERE s.election_year=2018)<>812581
 OR (SELECT count(*) FROM electoral_stage.option_vote v JOIN electoral_stage.election_series s ON s.series_id=v.series_id WHERE s.election_year=2018 AND v.votes IS NULL AND v.missing_cause='SOURCE_BLANK_UNCLASSIFIED')<>276022
 OR (SELECT count(*) FROM electoral_stage.section_tally t JOIN electoral_stage.election_series s ON s.series_id=t.series_id WHERE s.election_year=2018 AND t.total_votes IS NULL)<>0
 THEN RAISE EXCEPTION 'Conteos lote 2018 fuera de 28237/812581/276022/0'; END IF;
 IF EXISTS (
  SELECT 1 FROM electoral_stage.section_tally t
  JOIN electoral_stage.election_series s ON s.series_id=t.series_id
  JOIN electoral_stage.option_vote v ON v.tally_id=t.tally_id
  JOIN electoral_stage.option_column o ON o.option_id=v.option_id
  WHERE s.election_year=2018 AND t.total_votes IS NOT NULL AND o.option_type<>'VALID_VOTE_TOTAL'
  GROUP BY t.tally_id,t.total_votes
  HAVING sum(v.votes) IS DISTINCT FROM t.total_votes
 ) THEN RAISE EXCEPTION 'Suma opciones/total discordante año 2018'; END IF;
 RAISE NOTICE 'Lote 2018 OK: 28237 unidades, 812581 celdas, 276022 vacíos, 0 totales NULL';
END $$;
COMMIT;
-- Lote 2021: 15825 unidades, 322863 celdas, 59088 vacíos.
BEGIN;
SELECT r.series_id,r.unit_key,r.unit_kind,r.section_code,r.raw_cells->>'ID_ESTADO',r.district_federal_code,r.district_local_code,r.municipality_code,
 jsonb_build_object('ID_ESTADO',r.raw_cells->>'ID_ESTADO','ID_DISTRITO_FEDERAL',r.district_federal_code,'ID_DISTRITO_LOCAL',r.district_local_code,
 'ID_MUNICIPIO',r.municipality_code,'MUNICIPIO',r.raw_cells->>'MUNICIPIO','SECCION',r.section_code),'UNREVIEWED','UNRESOLVED'
FROM projected_rows r WHERE r.election_year=2021;
SELECT r.series_id,r.member_id,u.unit_id,r.raw_row_id,NULLIF(r.raw_cells->>'TOTAL_VOTOS','')::bigint,NULLIF(r.raw_cells->>'LISTA_NOMINAL','')::bigint,
 r.raw_cells->>'TOTAL_VOTOS',r.raw_cells->>'LISTA_NOMINAL',
 CASE WHEN r.raw_cells->>'TOTAL_VOTOS'='' THEN 'SOURCE_MISSING' WHEN r.raw_cells->>'TOTAL_VOTOS'='0' THEN 'OFFICIAL_ZERO' ELSE 'OBSERVED_DATA' END,
 CASE WHEN r.raw_cells->>'LISTA_NOMINAL'='' THEN 'SOURCE_MISSING' WHEN r.raw_cells->>'LISTA_NOMINAL'='0' THEN 'OFFICIAL_ZERO' ELSE 'OBSERVED_DATA' END,
 CASE WHEN r.raw_cells->>'TOTAL_VOTOS'='' THEN 'SOURCE_BLANK_UNCLASSIFIED' END,
 CASE WHEN r.raw_cells->>'LISTA_NOMINAL'='' THEN 'SOURCE_BLANK_UNCLASSIFIED' END
FROM projected_rows r JOIN electoral_stage.computation_unit u ON u.series_id=r.series_id AND u.unit_key=r.unit_key WHERE r.election_year=2021;
SELECT t.series_id,t.tally_id,o.option_id,NULLIF(r.raw_cells->>o.literal_header,'')::bigint,r.raw_cells->>o.literal_header,
 CASE WHEN r.raw_cells->>o.literal_header='' THEN 'SOURCE_MISSING' WHEN r.raw_cells->>o.literal_header='0' THEN 'OFFICIAL_ZERO' ELSE 'OBSERVED_DATA' END,
 CASE WHEN r.raw_cells->>o.literal_header='' THEN 'SOURCE_BLANK_UNCLASSIFIED' END
FROM electoral_stage.section_tally t JOIN electoral_stage.election_series s ON s.series_id=t.series_id
JOIN electoral_stage.raw_row r ON r.raw_row_id=t.raw_row_id JOIN electoral_stage.option_column o ON o.series_id=t.series_id
WHERE s.election_year=2021;
DO $$ BEGIN
 IF (SELECT count(*) FROM electoral_stage.computation_unit u JOIN electoral_stage.election_series s ON s.series_id=u.series_id WHERE s.election_year=2021)<>15825
 OR (SELECT count(*) FROM electoral_stage.section_tally t JOIN electoral_stage.election_series s ON s.series_id=t.series_id WHERE s.election_year=2021)<>15825
 OR (SELECT count(*) FROM electoral_stage.option_vote v JOIN electoral_stage.election_series s ON s.series_id=v.series_id WHERE s.election_year=2021)<>322863
 OR (SELECT count(*) FROM electoral_stage.option_vote v JOIN electoral_stage.election_series s ON s.series_id=v.series_id WHERE s.election_year=2021 AND v.votes IS NULL AND v.missing_cause='SOURCE_BLANK_UNCLASSIFIED')<>59088
 OR (SELECT count(*) FROM electoral_stage.section_tally t JOIN electoral_stage.election_series s ON s.series_id=t.series_id WHERE s.election_year=2021 AND t.total_votes IS NULL)<>3
 THEN RAISE EXCEPTION 'Conteos lote 2021 fuera de 15825/322863/59088/3'; END IF;
 IF EXISTS (
  SELECT 1 FROM electoral_stage.section_tally t
  JOIN electoral_stage.election_series s ON s.series_id=t.series_id
  JOIN electoral_stage.option_vote v ON v.tally_id=t.tally_id
  JOIN electoral_stage.option_column o ON o.option_id=v.option_id
  WHERE s.election_year=2021 AND t.total_votes IS NOT NULL AND o.option_type<>'VALID_VOTE_TOTAL'
  GROUP BY t.tally_id,t.total_votes
  HAVING sum(v.votes) IS DISTINCT FROM t.total_votes
 ) THEN RAISE EXCEPTION 'Suma opciones/total discordante año 2021'; END IF;
 RAISE NOTICE 'Lote 2021 OK: 15825 unidades, 322863 celdas, 59088 vacíos, 3 totales NULL';
END $$;
COMMIT;
DO $$ BEGIN
 IF EXISTS (
  SELECT 1 FROM electoral_stage.section_tally t
  JOIN electoral_stage.computation_unit u ON u.unit_id=t.unit_id
  JOIN electoral_stage.election_series s ON s.series_id=t.series_id
  WHERE s.election_year=2021 AND t.total_votes IS NULL
    AND NOT ((s.election_type='A' AND s.modality='UNICA' AND u.section_code IN ('163','2541'))
      OR (s.election_type='DL' AND s.modality='RP' AND u.section_code='1080'))
 ) THEN RAISE EXCEPTION 'Identidad de total NULL 2021 inesperada'; END IF;
 RAISE NOTICE 'Tres totales NULL 2021 preservados: A 163/2541 y DL RP 1080';
END $$;
-- Lote 2024: 29200 unidades, 528809 celdas, 6466 vacíos.
BEGIN;
SELECT r.series_id,r.unit_key,r.unit_kind,r.section_code,r.raw_cells->>'ID_ESTADO',r.district_federal_code,r.district_local_code,r.municipality_code,
 jsonb_build_object('ID_ESTADO',r.raw_cells->>'ID_ESTADO','ID_DISTRITO_FEDERAL',r.district_federal_code,'ID_DISTRITO_LOCAL',r.district_local_code,
 'ID_MUNICIPIO',r.municipality_code,'MUNICIPIO',r.raw_cells->>'MUNICIPIO','SECCION',r.section_code),'UNREVIEWED','UNRESOLVED'
FROM projected_rows r WHERE r.election_year=2024;
SELECT r.series_id,r.member_id,u.unit_id,r.raw_row_id,NULLIF(r.raw_cells->>'TOTAL_VOTOS','')::bigint,NULLIF(r.raw_cells->>'LISTA_NOMINAL','')::bigint,
 r.raw_cells->>'TOTAL_VOTOS',r.raw_cells->>'LISTA_NOMINAL',
 CASE WHEN r.raw_cells->>'TOTAL_VOTOS'='' THEN 'SOURCE_MISSING' WHEN r.raw_cells->>'TOTAL_VOTOS'='0' THEN 'OFFICIAL_ZERO' ELSE 'OBSERVED_DATA' END,
 CASE WHEN r.raw_cells->>'LISTA_NOMINAL'='' THEN 'SOURCE_MISSING' WHEN r.raw_cells->>'LISTA_NOMINAL'='0' THEN 'OFFICIAL_ZERO' ELSE 'OBSERVED_DATA' END,
 CASE WHEN r.raw_cells->>'TOTAL_VOTOS'='' THEN 'SOURCE_BLANK_UNCLASSIFIED' END,
 CASE WHEN r.raw_cells->>'LISTA_NOMINAL'='' THEN 'SOURCE_BLANK_UNCLASSIFIED' END
FROM projected_rows r JOIN electoral_stage.computation_unit u ON u.series_id=r.series_id AND u.unit_key=r.unit_key WHERE r.election_year=2024;
SELECT t.series_id,t.tally_id,o.option_id,NULLIF(r.raw_cells->>o.literal_header,'')::bigint,r.raw_cells->>o.literal_header,
 CASE WHEN r.raw_cells->>o.literal_header='' THEN 'SOURCE_MISSING' WHEN r.raw_cells->>o.literal_header='0' THEN 'OFFICIAL_ZERO' ELSE 'OBSERVED_DATA' END,
 CASE WHEN r.raw_cells->>o.literal_header='' THEN 'SOURCE_BLANK_UNCLASSIFIED' END
FROM electoral_stage.section_tally t JOIN electoral_stage.election_series s ON s.series_id=t.series_id
JOIN electoral_stage.raw_row r ON r.raw_row_id=t.raw_row_id JOIN electoral_stage.option_column o ON o.series_id=t.series_id
WHERE s.election_year=2024;
DO $$ BEGIN
 IF (SELECT count(*) FROM electoral_stage.computation_unit u JOIN electoral_stage.election_series s ON s.series_id=u.series_id WHERE s.election_year=2024)<>29200
 OR (SELECT count(*) FROM electoral_stage.section_tally t JOIN electoral_stage.election_series s ON s.series_id=t.series_id WHERE s.election_year=2024)<>29200
 OR (SELECT count(*) FROM electoral_stage.option_vote v JOIN electoral_stage.election_series s ON s.series_id=v.series_id WHERE s.election_year=2024)<>528809
 OR (SELECT count(*) FROM electoral_stage.option_vote v JOIN electoral_stage.election_series s ON s.series_id=v.series_id WHERE s.election_year=2024 AND v.votes IS NULL AND v.missing_cause='SOURCE_BLANK_UNCLASSIFIED')<>6466
 OR (SELECT count(*) FROM electoral_stage.section_tally t JOIN electoral_stage.election_series s ON s.series_id=t.series_id WHERE s.election_year=2024 AND t.total_votes IS NULL)<>0
 THEN RAISE EXCEPTION 'Conteos lote 2024 fuera de 29200/528809/6466/0'; END IF;
 IF EXISTS (
  SELECT 1 FROM electoral_stage.section_tally t
  JOIN electoral_stage.election_series s ON s.series_id=t.series_id
  JOIN electoral_stage.option_vote v ON v.tally_id=t.tally_id
  JOIN electoral_stage.option_column o ON o.option_id=v.option_id
  WHERE s.election_year=2024 AND t.total_votes IS NOT NULL AND o.option_type<>'VALID_VOTE_TOTAL'
  GROUP BY t.tally_id,t.total_votes
  HAVING sum(v.votes) IS DISTINCT FROM t.total_votes
 ) THEN RAISE EXCEPTION 'Suma opciones/total discordante año 2024'; END IF;
 RAISE NOTICE 'Lote 2024 OK: 29200 unidades, 528809 celdas, 6466 vacíos, 0 totales NULL';
END $$;
COMMIT;
SELECT s.election_year,s.election_type,s.modality,count(DISTINCT u.unit_id) AS unidades,count(v.option_id) AS celdas FROM electoral_stage.election_series s JOIN electoral_stage.computation_unit u ON u.series_id=s.series_id JOIN electoral_stage.section_tally t ON t.unit_id=u.unit_id JOIN electoral_stage.option_vote v ON v.tally_id=t.tally_id GROUP BY s.series_id,s.election_year,s.election_type,s.modality ORDER BY s.election_year,s.election_type,s.modality;
